import{_ as a,o,c as e,a0 as r}from"./chunks/framework.Caz7a20Z.js";const c=JSON.parse('{"title":"论文终于改完发出去了！还摸了摸微信小程序","description":"论文终于改完发给老师了，希望别再让我改了；今天还做了一些微信小程序嘿嘿；另外还得帮老师做例子，其余的论文也得继续推进了，加油。","frontmatter":{"title":"论文终于改完发出去了！还摸了摸微信小程序","date":"2026-09-17T00:00:00.000Z","tags":["日记"],"description":"论文终于改完发给老师了，希望别再让我改了；今天还做了一些微信小程序嘿嘿；另外还得帮老师做例子，其余的论文也得继续推进了，加油。"},"headers":[],"relativePath":"posts/diary-20260917.md","filePath":"posts/diary-20260917.md","lastUpdated":null}'),s={name:"posts/diary-20260917.md"};function p(n,t,i,d,l,u){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="论文终于改完发出去了-还摸了摸微信小程序" tabindex="-1">论文终于改完发出去了！还摸了摸微信小程序 <a class="header-anchor" href="#论文终于改完发出去了-还摸了摸微信小程序" aria-label="Permalink to &quot;论文终于改完发出去了！还摸了摸微信小程序&quot;">​</a></h1><p>今天有个时刻值得记一笔——<strong>论文，终于改完了</strong> 🎉。</p><h2 id="论文-改完了-发出去了" tabindex="-1">论文：改完了，发出去了！ <a class="header-anchor" href="#论文-改完了-发出去了" aria-label="Permalink to &quot;论文：改完了，发出去了！&quot;">​</a></h2><p>从&quot;再改一轮&quot;到&quot;再通读一遍&quot;到&quot;改参考文献&quot;，这条战线拉了不知道多少天，今天总算是收了尾：<strong>论文终于改完，发给老师了</strong> 📨✅。</p><p>那种感觉，怎么说呢——像背了很久的包终于卸下来了。前两天还在为汇报的事闹心，今天这个&quot;发送&quot;按钮按下去，整个人都松了一截。</p><p>至于质量，我不敢说完美，但该过的都过了、该磨的都磨了，拿出来不心虚。</p><p><strong>希望别让我再改了</strong> 🙏。</p><p>这句话大概每个改过论文的人都说过无数遍。理智上知道老师肯定还会提意见、肯定还有要动的地方，但情感上就是想许个愿：就到这儿吧，让我歇一轮吧哈哈。</p><h2 id="微信小程序-做了一些嘿嘿" tabindex="-1">微信小程序：做了一些嘿嘿 <a class="header-anchor" href="#微信小程序-做了一些嘿嘿" aria-label="Permalink to &quot;微信小程序：做了一些嘿嘿&quot;">​</a></h2><p>正事之外，今天还干了点&quot;副业&quot;——<strong>做了一些微信小程序</strong> 📱嘿嘿。</p><p>搞智能体搞久了，偶尔换个赛道动动手，做点轻巧的、能直接看见效果的东西，还挺解压的。小程序这玩意儿门槛低、见效快，写着写着有种&quot;我在做产品&quot;的错觉，比啃论文爽多了。</p><p>算是给最近高强度的论文节奏找了个调剂口，摸鱼也得摸得有产出嘛哈哈。</p><h2 id="接下来的活儿" tabindex="-1">接下来的活儿 <a class="header-anchor" href="#接下来的活儿" aria-label="Permalink to &quot;接下来的活儿&quot;">​</a></h2><p>轻松归轻松，手上的活儿还排着队：</p><p><strong>一是还得帮老师做例子</strong> 📊。老师那边的例子得给做出来，这个推不掉，排在前面。</p><p><strong>二是其余的论文也得继续了</strong> 📝。这篇告一段落，后面还有几篇在排队。前面用智能体推的那几篇，也到了该回头收拾的时候。</p><h2 id="就这样-加油" tabindex="-1">就这样，加油 <a class="header-anchor" href="#就这样-加油" aria-label="Permalink to &quot;就这样，加油&quot;">​</a></h2><p>今天总结一下：论文改完发出去了（里程碑 ✅），顺手摸了微信小程序（调剂 😄），后面还有老师的例子和别的论文等着。</p><p>一件收尾、一件摸鱼、一堆待办，这就是科研日常的真实样子哈哈。</p><p>明天继续搬砖，加油 💪！</p>',20)])])}const q=a(s,[["render",p]]);export{c as __pageData,q as default};
